<?php
/**
 * The "More from Kits" page of one plugin (generated by tools/build/gen-more-page.py), run on its own with stand-ins for
 * WordPress. Usage: php tools/validate/more-page-test.php <slug> <function prefix> <file relative to the plugin>
 * tools/validate/more-page-test.sh runs it for every plugin.
 */
// phpcs:disable -- a command-line test runner with WordPress stubs.
list( , $slug, $p, $rel ) = $argv + array( '', '', '', '' );
define( 'ABSPATH', __DIR__ . '/' );
$GLOBALS['flt'] = array();
$GLOBALS['reg'] = null;
$GLOBALS['plugins'] = array();
class WP_Error { public $code; public $msg; function __construct( $c = '', $m = '' ) { $this->code = $c; $this->msg = $m; } function get_error_message() { return $this->msg; } }
function is_wp_error( $x ) { return $x instanceof WP_Error; }
function add_action() {}
function __( $s ) { return $s; }
function apply_filters( $t, $v ) { return array_key_exists( $t, $GLOBALS['flt'] ) ? $GLOBALS['flt'][ $t ] : $v; }
function esc_url_raw( $u ) { return $u; }
function get_plugins() { return $GLOBALS['plugins']; }
function is_plugin_active( $f ) { return in_array( $f, $GLOBALS['active'] ?? array(), true ); }
function get_file_data( $file, $h ) {
	$src = file_get_contents( $file );
	$out = array();
	foreach ( $h as $k => $name ) {
		$out[ $k ] = preg_match( '/^[ \t\/*#@]*' . preg_quote( $name, '/' ) . ':(.*)$/mi', $src, $m ) ? trim( $m[1] ) : '';
	}
	return $out;
}
function wp_remote_get( $u, $a ) { return $GLOBALS['reg']; }
function wp_remote_retrieve_response_code( $r ) { return $r['code']; }
function wp_remote_retrieve_body( $r ) { return $r['body']; }

require dirname( __DIR__, 2 ) . "/plugins/$slug/$rel";
$fail = 0;
$ok   = function ( $n, $c ) use ( &$fail ) { if ( ! $c ) { $fail++; echo "FAIL: $n\n"; } };
$f = fn( $name ) => $p . '_more_' . $name;

$prods = $f( 'products' )();
$ok( "$slug: lists the other plugins, not itself", ! isset( $prods[ $slug ] ) && 6 === count( $prods ) );
$ok( "$slug: every address is a Kits page", ! array_filter( $prods, fn( $x ) => 0 !== strpos( $x[2], 'https://wugweb.com/plugins/' ) ) );

$GLOBALS['plugins'] = array( 'mailweb/mailweb.php' => array(), 'planweb/planweb.php' => array() );
$GLOBALS['active']  = array( 'mailweb/mailweb.php' );
$ok( "$slug: active", array( 'active', 'mailweb/mailweb.php' ) === $f( 'state' )( 'mailweb' ) );
$ok( "$slug: installed, not active", array( 'installed', 'planweb/planweb.php' ) === $f( 'state' )( 'planweb' ) );
$ok( "$slug: not installed", array( 'none', '' ) === $f( 'state' )( 'rankweb' ) );

$main = file_get_contents( dirname( __DIR__, 2 ) . "/plugins/$slug/$slug.php" );
$ok( "$slug: the direct build (with an Update URI) can install", $f( 'can_install' )() === (bool) preg_match( '/^[ \t\/*#@]*Update URI:\s*\S+/mi', $main ) );
define( 'KITS_NO_PLUGIN_INSTALLS', 1 );
$ok( "$slug: a constant switches installing off", false === $f( 'can_install' )() );

$sha = str_repeat( 'a', 64 );
$good = array( 'products' => array( 'rankweb' => array( 'type' => 'plugin', 'released' => true, 'prerelease' => false,
	'download' => array( 'commercial' => 'https://github.com/wugweb-git/Kits/releases/download/rankweb-v2.4.1/rankweb.zip' ), 'sha256' => array( 'commercial' => $sha ) ) ) );
$try = function ( $mut ) use ( $good, $f ) {
	$j = $good;
	$mut( $j['products']['rankweb'] );
	$GLOBALS['reg'] = array( 'code' => 200, 'body' => json_encode( $j ) );
	return $f( 'release' )( 'rankweb' );
};
$r = $try( function ( &$x ) {} );
$ok( "$slug: a good release gives its address and checksum", is_array( $r ) && $r['sha256'] === $sha && false !== strpos( $r['url'], '/releases/download/' ) );
$ok( "$slug: another host is refused", is_wp_error( $try( function ( &$x ) { $x['download']['commercial'] = 'https://evil.example/rankweb.zip'; } ) ) );
$ok( "$slug: another repository is refused", is_wp_error( $try( function ( &$x ) { $x['download']['commercial'] = 'https://github.com/someone/else/releases/download/v1/a.zip'; } ) ) );
$ok( "$slug: no checksum is refused", is_wp_error( $try( function ( &$x ) { $x['sha256']['commercial'] = 'xyz'; } ) ) );
$ok( "$slug: a pre-release is refused", is_wp_error( $try( function ( &$x ) { $x['prerelease'] = true; } ) ) );
$ok( "$slug: an unreleased product is refused", is_wp_error( $try( function ( &$x ) { $x['released'] = false; } ) ) );
$GLOBALS['reg'] = array( 'code' => 500, 'body' => '' );
$ok( "$slug: an unreachable registry is reported", is_wp_error( $f( 'release' )( 'rankweb' ) ) );
$GLOBALS['reg'] = array( 'code' => 200, 'body' => json_encode( $good ) );
$ok( "$slug: a product not in the registry is refused", is_wp_error( $f( 'release' )( 'mailweb' ) ) );
echo $fail ? "$fail failed\n" : "$slug: more page ok\n";
exit( $fail ? 1 : 0 );
